     1→//! This contains the scoring logic for peers.
     2→//!
     3→//! A peer's score is a rational number in the range [-100, 100].
     4→//!
     5→//! As the logic develops this documentation will advance.
     6→//!
     7→//! The scoring algorithms are currently experimental.
     8→use crate::service::gossipsub_scoring_parameters::GREYLIST_THRESHOLD as GOSSIPSUB_GREYLIST_THRESHOLD;
     9→use serde::Serialize;
    10→use std::cmp::Ordering;
    11→use std::sync::LazyLock;
    12→use std::time::Instant;
    13→use strum::AsRefStr;
    14→use tokio::time::Duration;
    15→
    16→static HALFLIFE_DECAY: LazyLock<f64> = LazyLock::new(|| -(2.0f64.ln()) / SCORE_HALFLIFE);
    17→
    18→/// The default score for new peers.
    19→pub(crate) const DEFAULT_SCORE: f64 = 0.0;
    20→/// The minimum reputation before a peer is disconnected.
    21→const MIN_SCORE_BEFORE_DISCONNECT: f64 = -20.0;
    22→/// The minimum reputation before a peer is banned.
    23→const MIN_SCORE_BEFORE_BAN: f64 = -50.0;
    24→/// If a peer has a lighthouse score below this constant all other score parts will get ignored and
    25→/// the peer will get banned regardless of the other parts.
    26→const MIN_LIGHTHOUSE_SCORE_BEFORE_BAN: f64 = -60.0;
    27→/// The maximum score a peer can obtain.
    28→const MAX_SCORE: f64 = 100.0;
    29→/// The minimum score a peer can obtain.
    30→const MIN_SCORE: f64 = -100.0;
    31→/// The halflife of a peer's score. I.e the number of seconds it takes for the score to decay to half its value.
    32→const SCORE_HALFLIFE: f64 = 600.0;
    33→/// The number of seconds we ban a peer for before their score begins to decay.
    34→const BANNED_BEFORE_DECAY: Duration = Duration::from_secs(12 * 3600); // 12 hours
    35→
    36→/// We weight negative gossipsub scores in such a way that they never result in a disconnect by
    37→/// themselves. This "solves" the problem of non-decaying gossipsub scores for disconnected peers.
    38→const GOSSIPSUB_NEGATIVE_SCORE_WEIGHT: f64 =
    39→    (MIN_SCORE_BEFORE_DISCONNECT + 1.0) / GOSSIPSUB_GREYLIST_THRESHOLD;
    40→const GOSSIPSUB_POSITIVE_SCORE_WEIGHT: f64 = GOSSIPSUB_NEGATIVE_SCORE_WEIGHT;
    41→
    42→/// A collection of actions a peer can perform which will adjust its score.
    43→/// Each variant has an associated score change.
    44→// To easily assess the behaviour of scores changes the number of variants should stay low, and
    45→// somewhat generic.
    46→#[derive(Debug, Clone, Copy, AsRefStr)]
    47→#[strum(serialize_all = "snake_case")]
    48→pub enum PeerAction {
    49→    /// We should not communicate more with this peer.
    50→    /// This action will cause the peer to get banned.
    51→    Fatal,
    52→    /// This peer's action is not malicious but will not be tolerated. A few occurrences will cause
    53→    /// the peer to get kicked.
    54→    /// NOTE: ~5 occurrences will get the peer banned
    55→    LowToleranceError,
    56→    /// An error occurred with this peer but it is not necessarily malicious.
    57→    /// We have high tolerance for this actions: several occurrences are needed for a peer to get
    58→    /// kicked.
    59→    /// NOTE: ~10 occurrences will get the peer banned
    60→    MidToleranceError,
    61→    /// An error occurred with this peer but it is not necessarily malicious.
    62→    /// We have high tolerance for this actions: several occurrences are needed for a peer to get
    63→    /// kicked.
    64→    /// NOTE: ~50 occurrences will get the peer banned
    65→    HighToleranceError,
    66→}
    67→
    68→/// Service reporting a `PeerAction` for a peer.
    69→#[derive(Debug)]
    70→pub enum ReportSource {
    71→    Gossipsub,
    72→    RPC,
    73→    Processor,
    74→    SyncService,
    75→    PeerManager,
    76→}
    77→
    78→impl From<ReportSource> for &'static str {
    79→    fn from(report_source: ReportSource) -> &'static str {
    80→        match report_source {
    81→            ReportSource::Gossipsub => "gossipsub",
    82→            ReportSource::RPC => "rpc_error",
    83→            ReportSource::Processor => "processor",
    84→            ReportSource::SyncService => "sync",
    85→            ReportSource::PeerManager => "peer_manager",
    86→        }
    87→    }
    88→}
    89→
    90→impl std::fmt::Display for PeerAction {
    91→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    92→        match self {
    93→            PeerAction::Fatal => write!(f, "Fatal"),
    94→            PeerAction::LowToleranceError => write!(f, "Low Tolerance Error"),
    95→            PeerAction::MidToleranceError => write!(f, "Mid Tolerance Error"),
    96→            PeerAction::HighToleranceError => write!(f, "High Tolerance Error"),
    97→        }
    98→    }
    99→}
   100→
   101→/// The expected state of the peer given the peer's score.
   102→#[derive(Debug, PartialEq, Clone, Copy)]
   103→pub(crate) enum ScoreState {
   104→    /// We are content with the peers performance. We permit connections and messages.
   105→    Healthy,
   106→    /// The peer should be disconnected. We allow re-connections if the peer is persistent.
   107→    ForcedDisconnect,
   108→    /// The peer is banned. We disallow new connections until it's score has decayed into a
   109→    /// tolerable threshold.
   110→    Banned,
   111→}
   112→
   113→impl std::fmt::Display for ScoreState {
   114→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   115→        match self {
   116→            ScoreState::Healthy => write!(f, "Healthy"),
   117→            ScoreState::Banned => write!(f, "Banned"),
   118→            ScoreState::ForcedDisconnect => write!(f, "Disconnected"),
   119→        }
   120→    }
   121→}
   122→
   123→/// A peer's score (perceived potential usefulness).
   124→///
   125→/// This simplistic version consists of a global score per peer which decays to 0 over time. The
   126→/// decay rate applies equally to positive and negative scores.
   127→#[derive(PartialEq, Clone, Debug, Serialize)]
   128→pub struct RealScore {
   129→    /// The global score.
   130→    // NOTE: In the future we may separate this into sub-scores involving the RPC, Gossipsub and
   131→    // lighthouse.
   132→    lighthouse_score: f64,
   133→    gossipsub_score: f64,
   134→    /// We ignore the negative gossipsub scores of some peers to allow decaying without
   135→    /// disconnecting.
   136→    ignore_negative_gossipsub_score: bool,
   137→    score: f64,
   138→    /// The time the score was last updated to perform time-based adjustments such as score-decay.
   139→    #[serde(skip)]
   140→    last_updated: Instant,
   141→}
   142→
   143→impl Default for RealScore {
   144→    fn default() -> Self {
   145→        RealScore {
   146→            lighthouse_score: DEFAULT_SCORE,
   147→            gossipsub_score: DEFAULT_SCORE,
   148→            score: DEFAULT_SCORE,
   149→            last_updated: Instant::now(),
   150→            ignore_negative_gossipsub_score: false,
   151→        }
   152→    }
   153→}
   154→
   155→impl RealScore {
   156→    /// Access to the underlying score.
   157→    fn recompute_score(&mut self) {
   158→        self.score = self.lighthouse_score;
   159→        if self.lighthouse_score <= MIN_LIGHTHOUSE_SCORE_BEFORE_BAN {
   160→            //ignore all other scores, i.e. do nothing here
   161→        } else if self.gossipsub_score >= 0.0 {
   162→            self.score += self.gossipsub_score * GOSSIPSUB_POSITIVE_SCORE_WEIGHT;
   163→        } else if !self.ignore_negative_gossipsub_score {
   164→            self.score += self.gossipsub_score * GOSSIPSUB_NEGATIVE_SCORE_WEIGHT;
   165→        }
   166→    }
   167→
   168→    fn score(&self) -> f64 {
   169→        self.score
   170→    }
   171→
   172→    /// Modifies the score based on a peer's action.
   173→    pub fn apply_peer_action(&mut self, peer_action: PeerAction) {
   174→        match peer_action {
   175→            PeerAction::Fatal => self.set_lighthouse_score(MIN_SCORE), // The worst possible score
   176→            PeerAction::LowToleranceError => self.add(-10.0),
   177→            PeerAction::MidToleranceError => self.add(-5.0),
   178→            PeerAction::HighToleranceError => self.add(-1.0),
   179→        }
   180→    }
   181→
   182→    fn set_lighthouse_score(&mut self, new_score: f64) {
   183→        self.lighthouse_score = new_score;
   184→        self.update_state();
   185→    }
   186→
   187→    /// Add an f64 to the score abiding by the limits.
   188→    fn add(&mut self, score: f64) {
   189→        let new_score = (self.lighthouse_score + score).clamp(MIN_SCORE, MAX_SCORE);
   190→        self.set_lighthouse_score(new_score);
   191→    }
   192→
   193→    fn update_state(&mut self) {
   194→        let was_not_banned = self.score > MIN_SCORE_BEFORE_BAN;
   195→        self.recompute_score();
   196→        if was_not_banned && self.score <= MIN_SCORE_BEFORE_BAN {
   197→            //we ban this peer for at least BANNED_BEFORE_DECAY seconds
   198→            self.last_updated += BANNED_BEFORE_DECAY;
   199→        }
   200→    }
   201→
   202→    /// Add an f64 to the score abiding by the limits.
   203→    #[cfg(test)]
   204→    pub fn test_add(&mut self, score: f64) {
   205→        self.add(score);
   206→    }
   207→
   208→    #[cfg(test)]
   209→    // reset the score
   210→    pub fn test_reset(&mut self) {
   211→        self.set_lighthouse_score(0f64);
   212→    }
   213→
   214→    // Set the gossipsub_score to a specific f64.
   215→    // Used in testing to induce score status changes during a heartbeat.
   216→    #[cfg(test)]
   217→    pub fn set_gossipsub_score(&mut self, score: f64) {
   218→        self.gossipsub_score = score;
   219→        self.update_state();
   220→    }
   221→
   222→    /// Applies time-based logic such as decay rates to the score.
   223→    /// This function should be called periodically.
   224→    pub fn update(&mut self) {
   225→        self.update_at(Instant::now())
   226→    }
   227→
   228→    /// Applies time-based logic such as decay rates to the score with the given now value.
   229→    /// This private sub function is mainly used for testing.
   230→    fn update_at(&mut self, now: Instant) {
   231→        // Decay the current score
